-- Architects & architecture firms, Hyderabad — Google Maps export, captured 28 Sep 2026.
--
-- 960 businesses after removing 8 in-file duplicates.
-- Loaded as prospects (is_client = false): desk-only, never on the public directory.
-- Loads through a staging table and skips accounts already in companies, matched on
-- name or the last 10 digits of the phone. Idempotent.

begin;

create temporary table _stage_arch (
  id text,
  name text,
  industry text,
  location text,
  open_positions integer,
  description text,
  website text,
  logo text,
  health text,
  margin_pct double precision,
  terms text,
  owner_id text,
  is_client boolean,
  contacts json,
  phone text,
  whatsapp text,
  address text,
  pincode text,
  rating double precision,
  reviews_count integer,
  maps_url text,
  latitude double precision,
  longitude double precision,
  source text,
  hours json,
  notes text,
  tags json
) on commit drop;

;

select s.id, s.name, s.industry, s.location, s.open_positions, s.description, s.website, s.logo, s.health, s.margin_pct, s.terms, s.owner_id, s.is_client, s.contacts, s.phone, s.whatsapp, s.address, s.pincode, s.rating, s.reviews_count, s.maps_url, s.latitude, s.longitude, s.source, s.hours, s.notes, s.tags
from _stage_arch s
where not exists (
  select 1 from public.companies c
  where lower(c.name) = lower(s.name)
)
and not exists (
  select 1 from public.companies c
  where c.phone is not null and s.phone is not null
    and length(regexp_replace(c.phone, '\D', '', 'g')) >= 10
    and right(regexp_replace(c.phone, '\D', '', 'g'), 10)
      = right(regexp_replace(s.phone, '\D', '', 'g'), 10)
)
on conflict (id) do nothing;

commit;
